#!/usr/bin/env node
import assert from 'node:assert/strict';import { buildPass35A15SnapshotEvidenceBundle } from '../../lib/market-integrity/pass35-snapshot-evidence-bundle.mjs';import { buildPass35A15WhaleEvidenceCoverage, verifyPass35A15WhaleEvidenceCoverage } from '../../lib/market-integrity/pass35-whale-evidence-bundle-runtime.mjs';
let checks=0;const check=(v,m)=>{checks+=1;assert.ok(v,m);};const now='2026-07-23T00:00:00Z';const assets=Array.from({length:100},(_,i)=>({canonicalAssetId:`crypto:coin${i+1}`,symbol:`C${i+1}`}));const snapshots=[];
function add(family,type,records){const payload=JSON.stringify(records);const b=buildPass35A15SnapshotEvidenceBundle({providerId:`${family}-${type}`,providerFamily:family,datasetType:type,sourceMode:'FILE_IMPORT',observedAt:now,payload,recordCount:records.length});snapshots.push({bundle:b.bundle,payload});}
for(const family of ['etherscan','alchemy','defillama']){const bindings=[];for(let i=0;i<80;i++)bindings.push({canonicalAssetId:assets[i].canonicalAssetId,chainId:1,address:`0x${String(i+1).padStart(40,'0')}`});add(family,'TOKEN_BINDINGS',bindings);}
const holders=[];const transfers=[];const labels=[];for(let i=0;i<80;i++){for(let h=0;h<60;h++)holders.push({canonicalAssetId:assets[i].canonicalAssetId,holderId:`0x${String(i*100+h+1).padStart(40,'0')}`,balance:1000-h});for(let t=0;t<120;t++)transfers.push({canonicalAssetId:assets[i].canonicalAssetId,eventId:`${i}:${t}`,from:`0x${String(t+1).padStart(40,'0')}`,to:`0x${String(t+2).padStart(40,'0')}`,amount:100+t});for(let l=0;l<12;l++)labels.push({canonicalAssetId:assets[i].canonicalAssetId,address:`0x${String(i*100+l+1).padStart(40,'0')}`,label:`exchange_${l}`,confidenceBps:9000});}
add('etherscan','TOKEN_HOLDERS',holders);add('alchemy','TOKEN_TRANSFERS',transfers);add('arkham_public','WALLET_LABELS',labels);
const coverage=buildPass35A15WhaleEvidenceCoverage({assets,snapshots,now});check(verifyPass35A15WhaleEvidenceCoverage(coverage),'verify');check(coverage.assetDenominator===100,'denominator');check(coverage.basicFunctionalReady===80&&coverage.proFunctionalReady===80&&coverage.advancedFunctionalReady===80,'tiers');check(coverage.rows.filter(r=>r.tiers.basic==='UNAVAILABLE').length===20,'unavailable retained');check(coverage.rows.slice(0,80).every(r=>r.exactBinding&&r.holderCount===60&&r.transferCount===120),'evidence counts');check(coverage.sellEnabled===false&&!coverage.liveClaimed,'fail closed');const t=structuredClone(coverage);t.assetDenominator=1;check(!verifyPass35A15WhaleEvidenceCoverage(t),'tamper');console.log(JSON.stringify({status:'PASS_A15_WHALE_EVIDENCE_BUNDLE',checks,assets:coverage.assetDenominator,basic:coverage.basicFunctionalReady,pro:coverage.proFunctionalReady,advanced:coverage.advancedFunctionalReady,snapshotBundles:coverage.snapshotBundleCount,paidDeliveryEligible:false,liveClaimed:false},null,2));
